INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('verkehrskontrolle-wien-schwerpunktaktion-raser-alkohol-oktober-2026','Verkehrskontrolle in Wien: 567 Tempo-Anzeigen bei Schwerpunktaktion','Bei einer nächtlichen Verkehrskontrolle in Wien hat die Polizei 567 Tempoverstöße angezeigt und 20 Führerscheine abgenommen. In Favoriten wurde ein Auto mit 120 km/h im Ortsgebiet gemessen.','Eine groß angelegte **Verkehrskontrolle in Wien** hat in der Nacht auf Samstag eine lange Liste an Verstößen ergeben. Die Landesverkehrsabteilung kontrollierte am Freitag, 23. Oktober, zwischen 19 Uhr und 2 Uhr früh im gesamten Stadtgebiet. Das geht aus einer Aussendung der Landespolizeidirektion Wien vom Sonntag hervor. Am Tag darauf fiel bei einer weiteren Kontrolle in Favoriten ein Lenker mit mehr als doppelt so hohem Tempo wie erlaubt auf.

## Verkehrskontrolle Wien: Wer beteiligt war

Die Aktion wurde von der Landesverkehrsabteilung Wien geleitet. Mit im Einsatz waren Beamtinnen und Beamte mehrerer Stadtpolizeikommanden, Sachverständige der Landesfahrzeugprüfstelle sowie die Gruppe Sofortmaßnahmen der Stadt Wien. Durch diese Zusammenarbeit konnten neben dem Fahrverhalten auch der technische Zustand von Fahrzeugen und mögliche unerlaubte Umbauten direkt vor Ort beurteilt werden.

## Alkohol, Drogen und Tempo: Die Bilanz

Im Mittelpunkt standen Alkohol und Drogen am Steuer sowie überhöhte Geschwindigkeit. Laut Polizei ergab die Nacht unter anderem folgende Zahlen:

- 719 Alkoholvortests und 11 Tests mit dem Alkomaten
- 7 Anzeigen wegen Lenkens in alkoholisiertem Zustand
- 7 Führerscheinabnahmen wegen Alkohol- oder Drogeneinfluss
- 567 Anzeigen wegen zu schnellen Fahrens
- 13 Führerscheinabnahmen wegen massiver Geschwindigkeitsüberschreitung
- 4 Anzeigen, weil Lenker keine gültige Lenkberechtigung hatten

Insgesamt wurden damit in einer einzigen Nacht 20 Führerscheine vorläufig abgenommen. Drei Personen verweigerten den Alkomattest, drei weitere eine amtsärztliche Untersuchung und eine Person die Blutabnahme. Zudem stellte die Polizei zwei Suchtmittel sicher.

## Technische Mängel und getunte Autos

Ein weiterer Schwerpunkt galt Fahrzeugen, die nicht verkehrssicher sind oder unerlaubt verändert wurden. 113 Anzeigen betrafen technische Mängel, 171 bezogen sich auf technische Veränderungen. 13 Fahrzeuge mussten zur genaueren Überprüfung zur Landesfahrzeugprüfstelle gebracht werden, bei 11 Autos wurden die Kennzeichen abgenommen. Außerdem gab es zwei Lärmmessungen.

Dazu kamen 393 Organmandate, 342 Anzeigen wegen sonstiger Übertretungen und 14 vor Ort eingehobene Strafen. 22 Fälle wurden per Schnellrichter erledigt. Eine Person wurde nach dem Verwaltungsstrafgesetz festgenommen, eine weitere nach dem Fremdengesetz. Die Polizei sieht in der Aktion einen spürbaren Beitrag zu mehr Sicherheit auf Wiens Straßen.

## Raser in Favoriten: 120 km/h auf der Laaer Berg Straße

Wie stark manche Lenker das Tempolimit ignorieren, zeigt ein Fall aus dem 10. Bezirk. Bei einer weiteren Kontrolle der Landesverkehrsabteilung am Samstag gegen 22 Uhr wurde auf der Laaer Berg Straße stadteinwärts ein Pkw mit 120 km/h gemessen, erlaubt sind dort 50 km/h. Nach Abzug der Messtoleranz blieb eine Überschreitung von 64 km/h.

Gegen den Lenker wird ein Verfahren zum Entzug des Führerscheins eingeleitet. Laut Polizei droht ihm zudem die Beschlagnahme seines Fahrzeugs. Seit der Verschärfung der Raser-Bestimmungen in der Straßenverkehrsordnung können Behörden bei besonders extremen Überschreitungen das Auto vorläufig beschlagnahmen.

## Weitere Kontrollen angekündigt

Die Wiener Polizei führt solche Schwerpunktaktionen regelmäßig durch, vor allem in den Abend- und Nachtstunden und an Wochenenden. Für Autofahrerinnen und Autofahrer bedeutet das: Wer mit Alkohol, unter Drogeneinfluss oder deutlich zu schnell unterwegs ist, muss in Wien jederzeit mit einer Kontrolle und dem sofortigen Verlust des Führerscheins rechnen.','chronik','Verkehr','wien','news','Presseinfo Redaktion','/assets/img/artikel/verkehrskontrolle-wien-schwerpunktaktion-raser-alkohol-oktober-2026.webp','Landespolizeidirektion Wien','https://www.polizei.gv.at/wien/presse/aussendungen/presse4d75.html?prid=6d48383935657634395a6f3d&pro=0','published','2026-10-26T05:55:00.000Z','2026-10-26T05:44:18.063Z','Verkehrskontrolle in Wien: 567 Tempo-Anzeigen','Verkehrskontrolle in Wien: Bei einer nächtlichen Schwerpunktaktion zog die Polizei 20 Führerscheine ab. Ein Lenker raste mit 120 km/h durch Favoriten.','Verkehrskontrolle Wien','["Verkehrskontrolle Wien","Schwerpunktaktion Polizei Wien","Raser Wien","Führerschein abgenommen","Alkohol am Steuer Wien","Laaer Berg Straße 120 km/h","Landesverkehrsabteilung Wien","Tuning Kontrolle Wien","Raser Favoriten"]','Verkehrskontrolle in Wien: Polizei kontrolliert nachts Autos auf einer Wiener Straße','Night-time police traffic checkpoint on a wide Viennese city street, police officers in reflective vests beside a stopped car, blue flashing lights reflecting on wet asphalt, classic Vienna apartment buildings in the background, no text, no logos, no readable signs','[{"q":"Wie viele Führerscheine wurden bei der Verkehrskontrolle in Wien abgenommen?","a":"Insgesamt 20: sieben wegen Alkohol- oder Drogeneinfluss und 13 wegen massiver Geschwindigkeitsüberschreitung."},{"q":"Wann fand die Schwerpunktaktion statt?","a":"Am Freitag, 23. Oktober 2026, von 19 Uhr bis 2 Uhr früh im Wiener Stadtgebiet."},{"q":"Was droht dem Raser von der Laaer Berg Straße?","a":"Gegen ihn läuft ein Führerscheinentzugsverfahren, laut Polizei droht ihm außerdem die Beschlagnahme des Fahrzeugs."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
